begin;
create table public.carmitra_user_roles(user_id uuid primary key references auth.users(id),role text not null check(role in ('admin')));
alter table public.carmitra_user_roles enable row level security;
revoke all on public.carmitra_user_roles from anon,authenticated;
grant select on public.carmitra_user_roles to authenticated;
create policy own_role on public.carmitra_user_roles for select to authenticated using(user_id=(select auth.uid()));
create function carmitra_internal.is_admin() returns boolean language sql stable security definer set search_path='' as $$ select auth.uid() is not null and exists(select 1 from public.carmitra_user_roles where user_id=auth.uid() and role='admin') $$;
revoke all on function carmitra_internal.is_admin() from public,anon;
grant execute on function carmitra_internal.is_admin() to authenticated;
create table public.carmitra_site_settings(id boolean primary key default true check(id),whatsapp_number text not null default '',toll_free text not null default '',support_email text not null default '',address text not null default '',legal_entity_name text not null default '',counters_enabled boolean not null default false,agreement_version text not null default '1',agreement_text text not null default 'Independent service partner: you retain 90% of completed job value. Follow verification, visible photo ID, blue/black T-shirt with shoes, before/after photographs, customer confirmation and safety requirements. Payouts are subject to settlement and admin review. Full legal terms require business approval.',late_cancellation_percent integer not null default 0 check(late_cancellation_percent between 0 and 100),channel_override_enabled boolean not null default false,channel_override_percent integer not null default 2 check(channel_override_percent between 0 and 10));
create table public.carmitra_partner_applications(id uuid primary key default gen_random_uuid(),user_id uuid unique not null references auth.users(id),full_name text not null,phone text not null check(phone~'^[6-9][0-9]{9}$'),email text not null,locality text not null references public.carmitra_areas(locality),experience integer not null check(experience between 0 and 60),skills integer[] not null check(cardinality(skills)>0),equipment boolean not null,documents jsonb not null,status text not null default 'pending' check(status in ('pending','approved','rejected')),review_note text not null default '',created_at timestamptz not null default now());
create table public.carmitra_partners(user_id uuid primary key references auth.users(id),application_id uuid unique not null references public.carmitra_partner_applications(id),full_name text not null,phone text not null,locality text not null references public.carmitra_areas(locality),skills integer[] not null,active boolean not null default true,agreement_signed_at timestamptz,agreement_version text,created_at timestamptz not null default now());
create table public.carmitra_channel_applications(id uuid primary key default gen_random_uuid(),user_id uuid unique not null references auth.users(id),full_name text not null,phone text not null check(phone~'^[6-9][0-9]{9}$'),tier text not null check(tier in ('zone','city','kit')),locality text not null references public.carmitra_areas(locality),experience text not null default '',status text not null default 'pending' check(status in ('pending','approved','rejected')),review_note text not null default '',created_at timestamptz not null default now());
create table public.carmitra_channel_partners(user_id uuid primary key references auth.users(id),application_id uuid unique not null references public.carmitra_channel_applications(id),full_name text not null,tier text not null,localities text[] not null,radius_km integer not null default 3 check(radius_km=3),active boolean not null default true,created_at timestamptz not null default now());
alter table public.carmitra_bookings add column partner_id uuid references public.carmitra_partners(user_id),add column partner_accepted boolean not null default false,add column before_photo text,add column after_photo text,add column customer_signature text,add column completed_at timestamptz;
alter table public.carmitra_bookings drop constraint carmitra_bookings_payment_status_check;
alter table public.carmitra_bookings add constraint carmitra_bookings_payment_status_check check(payment_status in ('cash_due','pending','paid','cash_collected','refund_pending','refunded'));
create table carmitra_internal.job_codes(booking_id uuid primary key references public.carmitra_bookings(id),code text not null,expires_at timestamptz not null,attempts integer not null default 0);
create table public.carmitra_wallet_transactions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),booking_id uuid references public.carmitra_bookings(id),kind text not null check(kind in ('online_earning','cash_earning','cash_platform_due','withdrawal_reserved','withdrawal_released')),amount_paise bigint not null,created_at timestamptz not null default now(),unique(booking_id,kind));
create table public.carmitra_payout_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),amount_paise integer not null check(amount_paise>0),upi text not null,status text not null default 'pending' check(status in ('pending','paid','rejected')),reference text,created_at timestamptz not null default now());
create table public.carmitra_cancellation_requests(id uuid primary key default gen_random_uuid(),booking_id uuid unique not null references public.carmitra_bookings(id),user_id uuid not null references auth.users(id),reason text not null,fee_paise integer not null check(fee_paise>=0),refund_paise integer not null check(refund_paise>=0),status text not null default 'pending' check(status in ('pending','refunded','no_refund','rejected')),provider_refund_id text,created_at timestamptz not null default now());
create table public.carmitra_reviews(id uuid primary key default gen_random_uuid(),booking_id uuid unique not null references public.carmitra_bookings(id),user_id uuid not null references auth.users(id),display_name text not null check(length(display_name) between 1 and 80),rating integer not null check(rating between 1 and 5),body text not null check(length(body) between 10 and 2000),published boolean not null default true,created_at timestamptz not null default now());
create table public.carmitra_warranty_claims(id uuid primary key default gen_random_uuid(),booking_id uuid not null references public.carmitra_bookings(id),user_id uuid not null references auth.users(id),description text not null,status text not null default 'pending' check(status in ('pending','resolved','rejected')),created_at timestamptz not null default now());
create table public.carmitra_blogs(id uuid primary key default gen_random_uuid(),title text not null,category text not null,body text not null,published boolean not null default false,created_at timestamptz not null default now());
create table public.carmitra_faqs(id bigint generated always as identity primary key,question text not null,answer text not null,active boolean not null default true,created_at timestamptz not null default now());
create table public.carmitra_subscription_plans(id uuid primary key default gen_random_uuid(),name text not null,price_paise integer not null check(price_paise>0),washes integer not null check(washes>0),valid_days integer not null default 30,active boolean not null default false,created_at timestamptz not null default now());
create table public.carmitra_user_subscriptions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),plan_id uuid not null references public.carmitra_subscription_plans(id),washes_left integer not null default 0,status text not null default 'requested' check(status in ('requested','active','expired')),expires_at timestamptz,created_at timestamptz not null default now());
create table public.carmitra_kits(id uuid primary key default gen_random_uuid(),name text not null,description text not null,mode text not null check(mode in ('sale','daily_rental','weekly_rental')),price_paise integer check(price_paise>0),active boolean not null default false,created_at timestamptz not null default now());
create table public.carmitra_kit_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),kit_id uuid not null references public.carmitra_kits(id),note text not null default '',status text not null default 'pending',created_at timestamptz not null default now());
create table public.carmitra_notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),message text not null,read_at timestamptz,created_at timestamptz not null default now());
create table public.carmitra_audit_logs(id bigint generated always as identity primary key,actor uuid references auth.users(id),action text not null,payload jsonb not null,created_at timestamptz not null default now());
-- One policy builder for explicit admin access; owner predicates remain table-specific.
do $$ declare t text;begin foreach t in array array['site_settings','partner_applications','partners','channel_applications','channel_partners','wallet_transactions','payout_requests','cancellation_requests','reviews','warranty_claims','blogs','faqs','subscription_plans','user_subscriptions','kits','kit_requests','notifications','audit_logs'] loop execute format('alter table public.carmitra_%I enable row level security',t);execute format('revoke all on public.carmitra_%I from anon, authenticated',t);execute format('grant select on public.carmitra_%I to authenticated',t);execute format('grant all on public.carmitra_%I to service_role',t);execute format('create policy admin_read on public.carmitra_%I for select to authenticated using (carmitra_internal.is_admin())',t);end loop;end $$;
-- Above format places the fixed prefix outside %I; these identifiers contain only underscores.
create policy settings_read on public.carmitra_site_settings for select to anon,authenticated using(true);
create policy blog_public on public.carmitra_blogs for select to anon,authenticated using(published);
create policy faq_public on public.carmitra_faqs for select to anon,authenticated using(active);
create policy plans_public on public.carmitra_subscription_plans for select to anon,authenticated using(active);
create policy kits_public on public.carmitra_kits for select to anon,authenticated using(active);
grant select on public.carmitra_site_settings,public.carmitra_blogs,public.carmitra_faqs,public.carmitra_subscription_plans,public.carmitra_kits to anon;
create policy application_own on public.carmitra_partner_applications for select to authenticated using(user_id=(select auth.uid()));
create policy partner_own on public.carmitra_partners for select to authenticated using(user_id=(select auth.uid()));
create policy channel_application_own on public.carmitra_channel_applications for select to authenticated using(user_id=(select auth.uid()));
create policy channel_own on public.carmitra_channel_partners for select to authenticated using(user_id=(select auth.uid()));
create policy wallet_own on public.carmitra_wallet_transactions for select to authenticated using(user_id=(select auth.uid()));
create policy payout_own on public.carmitra_payout_requests for select to authenticated using(user_id=(select auth.uid()));
create policy cancel_own on public.carmitra_cancellation_requests for select to authenticated using(user_id=(select auth.uid()));
create policy review_own on public.carmitra_reviews for select to authenticated using(user_id=(select auth.uid()));
create policy warranty_own on public.carmitra_warranty_claims for select to authenticated using(user_id=(select auth.uid()));
create policy subscription_own on public.carmitra_user_subscriptions for select to authenticated using(user_id=(select auth.uid()));
create policy kit_request_own on public.carmitra_kit_requests for select to authenticated using(user_id=(select auth.uid()));
create policy notification_own on public.carmitra_notifications for select to authenticated using(user_id=(select auth.uid()));
create policy assigned_booking on public.carmitra_bookings for select to authenticated using(partner_id=(select auth.uid()) or carmitra_internal.is_admin());
create policy logs_admin on public.carmitra_booking_status_logs for select to authenticated using(carmitra_internal.is_admin());
create policy services_admin on public.carmitra_services for select to authenticated using(carmitra_internal.is_admin());
-- Public reviews return only publication fields, never customer IDs or booking IDs.
create function carmitra_internal.public_reviews() returns jsonb language sql stable security definer set search_path='' as $$ select coalesce(jsonb_agg(jsonb_build_object('display_name',display_name,'rating',rating,'body',body,'created_at',created_at)),'[]'::jsonb) from public.carmitra_reviews where published $$;
create function public.carmitra_public_reviews() returns jsonb language sql security invoker set search_path='' as $$select carmitra_internal.public_reviews()$$;
grant usage on schema carmitra_internal to anon;
revoke all on function carmitra_internal.public_reviews(),public.carmitra_public_reviews() from public;
grant execute on function carmitra_internal.public_reviews(),public.carmitra_public_reviews() to anon,authenticated;
create index on public.carmitra_bookings(partner_id);
create index on public.carmitra_wallet_transactions(user_id,created_at);
create index on public.carmitra_payout_requests(user_id);
create index on public.carmitra_cancellation_requests(user_id);
create index on public.carmitra_user_subscriptions(user_id);
create index on public.carmitra_notifications(user_id);
create index on public.carmitra_warranty_claims(user_id);
create index on public.carmitra_kit_requests(user_id);
create index on public.carmitra_reviews(user_id);
create function carmitra_internal.media_access(path text) returns boolean language sql stable security definer set search_path='' as $$select auth.uid() is not null and (carmitra_internal.is_admin() or exists(select 1 from public.carmitra_bookings b where b.id::text=split_part(path,'/',2) and (b.user_id=auth.uid() or b.partner_id=auth.uid())))$$;
revoke all on function carmitra_internal.media_access(text) from public,anon;
grant execute on function carmitra_internal.media_access(text) to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('carmitra-documents','carmitra-documents',false,5242880,array['image/jpeg','image/png','image/webp','application/pdf']),('carmitra-job-media','carmitra-job-media',false,5242880,array['image/jpeg','image/png','image/webp']);
create policy carmitra_docs_insert on storage.objects for insert to authenticated with check(bucket_id='carmitra-documents' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy carmitra_docs_read on storage.objects for select to authenticated using(bucket_id='carmitra-documents' and ((storage.foldername(name))[1]=(select auth.uid())::text or carmitra_internal.is_admin()));
create policy carmitra_media_insert on storage.objects for insert to authenticated with check(bucket_id='carmitra-job-media' and (storage.foldername(name))[1]=(select auth.uid())::text and carmitra_internal.media_access(name));
create policy carmitra_media_read on storage.objects for select to authenticated using(bucket_id='carmitra-job-media' and carmitra_internal.media_access(name));
commit;
